set -euo pipefail
SRC=/opt/brigada-core-src
install -d "$SRC/$(dirname 'src/main/java/dev/brigada13/core/death/DeathItemService.java')"
printf '%s' '' | base64 -d > "$SRC/src/main/java/dev/brigada13/core/death/DeathItemService.java"
install -d "$SRC/$(dirname 'src/main/java/dev/brigada13/core/state/DeathItemState.java')"
printf '%s' '' | base64 -d > "$SRC/src/main/java/dev/brigada13/core/state/DeathItemState.java"
install -d "$SRC/$(dirname 'src/main/resources/data/minecraft/tags/dialog/pause_screen_additions.json')"
printf '%s' 'ewogICJyZXBsYWNlIjogZmFsc2UsCiAgInZhbHVlcyI6IFsKICAgICJicmlnYWRhX2NvcmU6bWFpbiIKICBdCn0K' | base64 -d > "$SRC/src/main/resources/data/minecraft/tags/dialog/pause_screen_additions.json"

cd "$SRC"
if command -v gradle >/dev/null 2>&1; then
  GRADLE_BIN=$(command -v gradle)
elif [ -x /opt/gradle-9.6.1/bin/gradle ]; then
  GRADLE_BIN=/opt/gradle-9.6.1/bin/gradle
else
  echo 'Gradle 9.6.1 not found' >&2
  exit 2
fi
"$GRADLE_BIN" --no-daemon clean build
JAR=$(find build/libs -maxdepth 1 -type f -name '*.jar' ! -name '*sources*' ! -name '*dev*' | head -n 1)
test -n "$JAR"
BACKUP="/opt/minecraft/server/backups/brigada-core-0.1.0-$(date -u +%Y%m%dT%H%M%SZ).jar"
cp /opt/minecraft/server/mods/brigada-core-0.1.0.jar "$BACKUP"
install -m 0644 "$JAR" /opt/minecraft/server/mods/brigada-core-0.1.0.jar
systemctl restart minecraft.service
sleep 12
echo STATUS
systemctl is-active minecraft.service
echo VERSION
unzip -p /opt/minecraft/server/mods/brigada-core-0.1.0.jar fabric.mod.json
echo PAUSE_BUTTON
unzip -p /opt/minecraft/server/mods/brigada-core-0.1.0.jar data/minecraft/tags/dialog/pause_screen_additions.json
echo SHA256
sha256sum /opt/minecraft/server/mods/brigada-core-0.1.0.jar
echo LOG
journalctl -u minecraft.service -n 120 --no-pager | grep -E 'Fabric|World Core|Done \(|ERROR|Exception' | tail -n 40
